#!/usr/bin/env python3
"""Russia flagship course data, part 1 (RU-01 to RU-08). HELD for a lawyer's check. Own wording; no brand, person or institution names; no fees."""

COURSES = [
dict(
 id='RU-01', title='Fishing and Seafood Business',
 summary='Plan and run a small, lawful fishing-product or seafood trading business: from catch or purchase records and cold-chain control to costing, customers and compliance. Built for people who handle fish and seafood, not for people who want to fish without permission.',
 level='L4 Practitioner',
 outcomes=[
  ('Understand', 'Explain the main steps from catch or purchase to customer and where the permits, records and inspections sit in that chain.'),
  ('Apply', 'Calculate yield, landed cost per kilogram and gross margin for a batch of fish or seafood.'),
  ('Analyse', 'Compare cold-chain options and storage times for fresh, chilled, frozen and salted product and find the weak points.'),
  ('Evaluate', 'Judge a supplier or a sales channel against price, quality, paperwork and risk.'),
  ('Create', 'Build a one-year plan with a batch costing sheet, a cold-chain log, a compliance checklist and a cash plan.')],
 task='Prepare a costed, documented plan for buying, storing and selling one fish or seafood product line, with a cold-chain log and a compliance checklist.',
 condition='Individual work over 6 weeks, using a spreadsheet, a calculator, a probe thermometer log template and the course templates; sample prices are supplied or taken from local suppliers.',
 standard='Batch costing correct to within 2 percent; cold-chain log complete with times and temperatures for 7 consecutive days; checklist covers every permit and record the learner confirmed with the competent authority; 8 of 10 check answers right.',
 who='Small traders, cooperative members, processors, shop and market stall owners, and people planning to enter the seafood trade.',
 req='Basic arithmetic and a spreadsheet. No prior sector experience is needed.',
 safety='Fishing, aquaculture and trade in fish products are regulated: catch rights and quotas, vessel and crew rules, veterinary and sanitary control, labelling and traceability all apply. This course does not give legal advice and does not tell anyone how to fish, land or sell without the required permissions. Before any real activity, check with the competent Russian authority and a local adviser which permits, quotas and inspections apply to you. Work at sea and on ice is dangerous; follow qualified safety training. Margins vary and no profit is promised.',
 evidence='Evidence products: batch costing sheet, 7-day cold-chain log, supplier comparison, compliance checklist, one-year cash plan.',
 modules=[
  ('The seafood value chain', 'Understand', 4,
   'Fish and seafood move from catch or farm to landing, primary handling, storage, processing, transport and sale. Each step changes value, risk and paperwork.',
   ['Name the steps: catch or harvest, landing, sorting, chilling, processing, packing, storage, transport, sale.',
    'Separate the roles: fisher, farmer, processor, wholesaler, retailer, caterer. A small firm often plays two roles.',
    'Mark where a record is kept at each step: catch or purchase document, batch number, temperature, destination.',
    'Explain why product that cannot be traced to a source is a risk for every buyer.'],
   'A trader buys 500 kg of whole chilled fish at 180 RUB/kg and sells it as fillets. Draw the chain with five steps and list one record needed at each.',
   'Draw the chain for one product you know and mark records and inspection points.',
   'Chain has at least 6 steps and a record named at each; roles are separated correctly.'),
  ('Species, quality and freshness', 'Understand', 4,
   'Quality is judged by simple sensory and temperature checks before any laboratory test. A buyer who can grade product protects both margin and customers.',
   ['Check fresh fish by eye, gill colour, smell, flesh firmness and clear eyes; record the result as pass or reject.',
    'Know that chilled fish is held near 0 to 2 degrees C and frozen product at -18 degrees C or colder.',
    'Describe how shellfish and some species carry higher risk and need extra handling rules.',
    'Use a grade sheet with 5 criteria scored 0 to 2 and a clear reject score.'],
   'A 20 kg box scores 9 of 10 on the grade sheet and passes at 8. Another box scores 6 and is rejected; at 180 RUB/kg the avoided loss on a 20 kg box is 3,600 RUB.',
   'Grade 5 samples (real or photos) with the sheet and justify each reject.',
   'Grades agree with a mentor on at least 4 of 5 samples.'),
  ('Yield, waste and landed cost', 'Apply', 5,
   'Selling price must cover the true cost of usable meat, not of the whole fish. Yield and waste decide margin.',
   ['Yield percent = usable weight divided by purchased weight times 100.',
    'Landed cost = purchase price plus transport, ice, packing and handling, divided by usable kilograms.',
    'Track waste and by-products separately; some by-products can be sold or must be disposed of by rule.',
    'Add overhead per kilogram: storage energy, labour, cleaning, losses.'],
   'Buy 400 kg whole fish at 160 RUB/kg = 64,000 RUB. Transport and ice 4,000 RUB. Fillet yield 45 percent = 180 kg. Landed cost = 68,000 / 180 = 377.8 RUB/kg. At a sale price of 520 RUB/kg gross margin is 142.2 RUB/kg (27.3 percent).',
   'Build a costing sheet for two products and compare their margins per kilogram.',
   'Both sheets are formula-driven and arithmetic is within 2 percent of the mentor key.'),
  ('Cold chain and storage', 'Analyse', 5,
   'Temperature control is the central safety and quality tool. Time above the limit is cumulative.',
   ['Log temperature at receiving, in storage, in transport and at handover, with time and initials.',
    'Size ice or refrigeration: product weight, start temperature, journey time and outside heat.',
    'Plan storage rotation: first in, first out, with date labels on every box.',
    'Define corrective actions: product quarantined, supplier told, record kept.'],
   'A chilled load of 300 kg travels 6 hours. The limit is 4 degrees C at delivery; the probe reads 7 degrees C. The batch is held and the carrier asked for the transport log; the 300 kg at 250 RUB/kg (75,000 RUB) is at risk and is not sold until cleared.',
   'Keep a 7-day cold-chain log for a real or simulated store and mark two deviations with actions.',
   'Log complete for 7 days, deviations named, actions written and dated.'),
  ('Preservation and processing basics', 'Understand', 4,
   'Salting, smoking, freezing and canning change shelf life and risk. Each needs its own control points.',
   ['Compare freezing, salting, drying, smoking and canning for time, cost and risk.',
    'Explain why hot and cold smoking, and brining strength, need controlled and recorded values.',
    'Keep batch records so a problem can be traced and recalled.',
    'Note that processing premises and some processes need approval; ask the competent authority first.'],
   'Salting 100 kg of fish with 8 kg of salt uses 8 percent salt by weight; at 25 RUB/kg salt costs 200 RUB, small against the fish value, so control is about safety and not cost.',
   'Write a one-page batch record for one processed product.',
   'Record has batch number, dates, weights, temperatures and destination.'),
  ('Markets, customers and pricing', 'Analyse', 5,
   'Seafood is sold to shops, restaurants, markets, institutions and households. Each channel pays differently and pays at a different speed.',
   ['Map 4 channels with price, volume, payment days and paperwork.',
    'Set price from cost plus target margin, then test against the local market.',
    'Plan around seasons and weather; hold a cash reserve for slow weeks.',
    'Judge a customer on payment record, not only on order size.'],
   'A restaurant takes 40 kg/week at 520 RUB/kg paid in 14 days; a market stall takes 25 kg/week at 560 RUB/kg paid daily. Weekly sales are 20,800 and 14,000 RUB; the stall has better cash timing despite lower volume.',
   'Compare two channels in a table including payment days and risk.',
   'Table covers price, volume, payment days and a stated choice.'),
  ('Compliance, permits and safety', 'Evaluate', 5,
   'The rules around fishing and seafood are strict and enforced. A lawful business starts with knowing which rules apply before the first purchase.',
   ['List the kinds of permission to check: catch rights and quotas, vessel and crew rules, premises and veterinary approval, product labelling and traceability, tax and registration.',
    'Keep supporting documents for every batch and keep them available for inspection.',
    'Never buy product without a clear source document.',
    'Identify safety hazards: cold, wet decks, ice, machinery, chemicals; use protective gear and training.'],
   'A seller offers 1,000 kg at 100 RUB/kg, well below the 180 RUB/kg market price, with no source papers. Savings on paper are 80,000 RUB but the risk is seizure and loss of the whole stock, so the offer is declined.',
   'Build a compliance checklist for one product and confirm each line with a named authority or adviser.',
   'Checklist has every permit and record type; each line has an owner and a confirmed answer or an open question.'),
  ('Plan, cash and review', 'Create', 4,
   'A plan joins costing, cold chain, sales and compliance into one view and one cash flow.',
   ['Build a 12-month cash plan with monthly sales, costs and a reserve.',
    'Set 5 simple indicators: yield, margin per kg, rejects, days to pay and stock days.',
    'Plan a 90-day review and list the decisions it can change.',
    'State the main risks and a response for each.'],
   'Monthly sales 300 kg x 520 = 156,000 RUB; cost of goods 300 x 378 = 113,400 RUB; overhead 20,000 RUB; surplus 22,600 RUB, which is the reserve builder and not guaranteed income.',
   'Assemble and present the one-year plan.',
   'Plan ties costing, log, checklist and cash; a mentor finds no arithmetic error above 2 percent.')],
 quiz=[
  ('What is yield percent?', 'Usable weight divided by purchased weight, times 100.'),
  ('What is landed cost?', 'The full cost to bring usable product to the point of sale, divided by usable kilograms.'),
  ('At what temperature is frozen fish normally stored?', 'At -18 degrees C or colder.'),
  ('Why is a batch number used?', 'So product can be traced to its source and recalled if a problem is found.'),
  ('A load arrives above the temperature limit. What do you do?', 'Quarantine it, record the reading, tell the supplier and carrier, and do not sell it until cleared.'),
  ('Why refuse stock with no source papers even at a low price?', 'It may be unlawful, can be seized, and the loss can exceed the saving.'),
  ('What does first in, first out mean?', 'The oldest stock is sold first, using date labels.'),
  ('Name two sensory freshness checks.', 'Clear eyes and a fresh smell (also gill colour and firm flesh).'),
  ('Who decides which permits apply to you?', 'The competent Russian authority; check with it and a local adviser.'),
  ('Why does a cash reserve matter in this trade?', 'Catch, weather and demand vary, so slow weeks must be covered.')],
 rubric=[
  ('Costing', 'Wrong yield or missing costs', 'Correct yield and landed cost within 2 percent', 'Compares products and tests price changes'),
  ('Cold chain', 'Gaps in the log', '7-day log complete with actions', 'Finds a root cause and fixes it'),
  ('Compliance', 'Permits missing', 'All permit and record types listed and confirmed', 'Adds an inspection-readiness drill'),
  ('Market', 'No channel comparison', 'Two channels compared with payment days', 'Chooses a channel mix with reasons'),
  ('Plan', 'Plan without cash view', '12-month cash plan with reserve', 'Adds scenarios and a 90-day review')],
 ladder=[
  'L1 Basic: can name the steps from catch to customer and say why fish must be kept cold (needs a guide).',
  'L2 Awareness: can read a batch label and a temperature log and spot an obvious problem.',
  'L3 Foundation: can grade fresh product and calculate yield and landed cost for one batch with help.',
  'L4 Practitioner: can run a small, lawful product line with costing, cold-chain log and a compliance checklist.',
  'L5 Specialist: can design processing and storage controls and negotiate with suppliers and chains (needs a qualified veterinary or food-safety adviser for approvals).',
  'L6 Advanced: can lead several product lines, audit a supply chain and prepare for inspection.',
  'L7 Super expert: can shape sector practice across regions, training others and advising on sustainable sourcing (within the law and under the competent authority).'],
 jobs=[
  ('Seafood buyer', 'Selects and checks suppliers and grades product for a trader or chain.'),
  ('Cold-store operator', 'Runs temperature, rotation and records in a store.'),
  ('Fish processing assistant', 'Fillets, packs and records batches under food-safety rules.'),
  ('Seafood sales representative', 'Sells to shops and restaurants and manages orders and payments.'),
  ('Small seafood trader', 'Runs a lawful buying and selling business with costing and compliance.')],
 next='Next generic courses: Food Safety and Hygiene; Small Business Finance; Cold Chain and Logistics.'),

dict(
 id='RU-02', title='Farming',
 summary='Plan and manage a small crop and livestock farm as a business: land and season planning, input and yield calculations, animal and crop care, records and cash flow. Focuses on sound practice and legal basics.',
 level='L4 Practitioner',
 outcomes=[
  ('Understand', 'Explain the farm year and how soil, water, weather and labour shape what can be grown or kept.'),
  ('Apply', 'Calculate seed, fertiliser and feed quantities and a gross margin per hectare or per animal.'),
  ('Analyse', 'Compare crop and livestock options by cost, risk, labour and cash timing.'),
  ('Evaluate', 'Judge a farm record set for gaps in soil, input, health and sales information.'),
  ('Create', 'Build a one-year farm plan with a calendar, input budget, record system and cash plan.')],
 task='Prepare a farm plan for one holding with a season calendar, input budget, gross margin and record system.',
 condition='Individual work over 6 weeks with a calculator, spreadsheet, a plot map (sketch is enough) and sample local prices and yields.',
 standard='Input quantities correct to within 5 percent; gross margins reconcile to the budget; record system covers inputs, health, harvest and sales; 8 of 10 check answers right.',
 who='Smallholders, family farm members, farm workers, cooperative members and people planning to start farming.',
 req='Basic arithmetic. No prior farming experience is needed.',
 safety='Farming is subject to rules on land use and tenure, plant protection products, fertilisers, animal identification and health, veterinary control, food safety and the environment. This course gives no legal advice. Confirm which permits, registrations and rules apply to your land and activity with the competent Russian authority and a local adviser. Machinery, pesticides, animals and heights cause serious injury; use trained operators and protective gear, and follow the label on every product. Yields and prices vary with weather; no income is promised.',
 evidence='Evidence products: season calendar, input budget, gross margin sheet, record sheets, cash plan.',
 modules=[
  ('The farm as a system', 'Understand', 4,
   'A farm joins land, water, plants, animals, labour and money. A change in one part moves the others.',
   ['List the resources: land area, soil, water, labour days, equipment, buildings, cash.',
    'Draw the flows: manure to field, feed from field, grain to market, cash back to inputs.',
    'Name the main risks: weather, pests, disease, price, labour, access to market.',
    'Set farm goals in measures: tonnes, litres, margin per hectare.'],
   'A 5-hectare holding has 3 ha for grain, 1 ha for vegetables and 1 ha for fodder, keeping 4 cows. Fodder of 1 ha at 6 tonnes/ha dry matter feeds only part of the herd, so purchased feed is needed. Check: 4 cows x 18 kg x 200 days = 14,400 kg need; 6,000 kg grown covers about 42 percent; the 8,400 kg gap at 12 RUB/kg costs 100,800 RUB.',
   'Draw the system diagram for a real or model farm and list three risks with responses.',
   'Diagram has all resources and flows; risks have a named response.'),
  ('Soil, water and climate', 'Understand', 4,
   'Soil type, acidity, organic matter and water supply decide crop choice and input need. Short growing seasons demand early-maturing varieties.',
   ['Read a soil test: pH, organic matter, major nutrients; know what the numbers mean for the crop.',
    'Describe how drainage, slope and frost pockets change plot use.',
    'Plan water: source, amount per hectare, timing and storage.',
    'Use local weather records to find the last frost, first frost and growing days.'],
   'A soil test shows pH 5.2 for a crop needing 6.0 to 6.5. Liming at the rate advised by the test lab corrects acidity; a 5 ha field at 3 tonnes/ha needs 15 tonnes of lime.',
   'Summarise a soil test and give a plot plan for two crops.',
   'Test values are read correctly and the plan matches the climate.'),
  ('Crop planning and rotation', 'Apply', 5,
   'A rotation breaks pest and disease cycles and spreads workload. Seed and fertiliser rates come from target yield and local advice.',
   ['Design a 4-year rotation including a legume or fodder break.',
    'Calculate seed: area x seed rate (kg/ha); allow for germination.',
    'Calculate nutrient need from target yield and soil supply.',
    'Set sowing and harvest windows and match them to labour.'],
   'Wheat at 200 kg/ha seed on 3 ha needs 600 kg. At 35 RUB/kg seed cost is 21,000 RUB. Target yield 3.5 t/ha gives 10.5 t; at 15,000 RUB/t revenue is 157,500 RUB.',
   'Write a 4-year rotation and a seed and fertiliser list for year 1.',
   'Quantities are within 5 percent of the mentor key.'),
  ('Plant health and safe use of inputs', 'Evaluate', 4,
   'Scouting, resistant varieties and rotation come before chemical control. Any plant protection product must be approved and used exactly as labelled.',
   ['Scout weekly and record pest and disease counts against action levels.',
    'Read labels: dose, safe interval before harvest, protective gear, storage and disposal.',
    'Store products locked, away from food and children, with a spill plan.',
    'Keep a spray record: date, product, dose, area, weather, operator.'],
   'A label gives 2 L/ha for 4 ha: 8 L total; a 2 L over-dose costs product, risks residues and breaks the label. The safe interval of 21 days before harvest fixes the last spray date.',
   'Prepare a spray record and a storage checklist.',
   'Record has all fields; checklist matches the label rules.'),
  ('Livestock care and health', 'Apply', 5,
   'Animal welfare, feed, housing and health plans drive output. Disease control depends on prevention and veterinary guidance.',
   ['Plan feed by animal group using dry matter need and ration balance.',
    'Provide shelter, clean water and space suited to the species and season.',
    'Keep identification, movement and treatment records and follow veterinary instructions and withdrawal periods.',
    'Report notifiable disease signs to the veterinary authority at once.'],
   'A dairy cow eating 18 kg dry matter/day needs 18 x 200 = 3,600 kg over 200 winter days. For 4 cows that is 14.4 tonnes; at 12 RUB/kg this is 172,800 RUB of feed.',
   'Calculate winter feed for a herd and prepare a health record template.',
   'Feed total within 5 percent; record has ID, treatment, dose and withdrawal date.'),
  ('Costs, margins and marketing', 'Analyse', 5,
   'Gross margin = output value minus variable costs. It lets you rank enterprises before you count fixed costs.',
   ['List variable costs: seed, fertiliser, feed, vet, fuel, hired labour.',
    'Compute margin per hectare or per animal and compare options.',
    'Choose sales routes: direct, cooperative, processor, market; compare price, volume and payment time.',
    'Check break-even yield or price.'],
   'Potatoes: yield 20 t/ha x 14,000 RUB/t = 280,000 RUB. Variable costs 190,000 RUB/ha. Margin 90,000 RUB/ha. Break-even yield = 190,000 / 14,000 = 13.6 t/ha.',
   'Compute margins for three enterprises and rank them.',
   'Margins within 3 percent; ranking has stated reasons.'),
  ('Records, land and rules', 'Evaluate', 4,
   'Good records support management, credit, inspection and any lawful support or subsidy a farm applies for.',
   ['Keep field, input, animal, harvest, sales and cost records in a single place.',
    'Know the types of paper that matter: land tenure, registration, product and animal documents.',
    'Check any support scheme rules and deadlines with the competent authority before relying on them.',
    'Protect people: equipment guards, rest times, first-aid kit.'],
   'A farm sells 10 t of grain at 15,000 RUB/t = 150,000 RUB. Missing weight tickets would leave 150,000 RUB of income undocumented, which is an avoidable audit and credit problem.',
   'Audit a sample record set and list five gaps.',
   'At least five true gaps found, each with a fix.'),
  ('Whole-farm plan and cash', 'Create', 4,
   'The plan joins crops, animals, labour and cash with a calendar.',
   ['Build a month-by-month cash plan; mark when inputs are paid and when sales arrive.',
    'Plan labour days per month and find peaks.',
    'Prepare for a bad year: reserve, insurance where available and lawful, flexible costs.',
    'Set a review after harvest and after winter.'],
   'Input spend 300,000 RUB in April; sales 520,000 RUB in October. The gap needs 300,000 RUB of working capital for 6 months; at an interest rate of 15 percent per year the cost is about 22,500 RUB.',
   'Present a one-year farm plan.',
   'Plan reconciles calendar, budget and cash with a stated reserve.')],
 quiz=[
  ('What is gross margin?', 'Output value minus variable costs.'),
  ('How do you find the seed needed?', 'Area times seed rate, adjusted for germination.'),
  ('Why use a rotation?', 'It breaks pest and disease cycles, spreads workload across the year, and balances nutrient use because legumes and fodder crops restore what cereals and roots remove from the soil.'),
  ('What must you read on a plant protection label?', 'Dose, safe interval before harvest, protective gear, storage and disposal.'),
  ('What is a withdrawal period?', 'The set number of days after a veterinary treatment before milk, meat or eggs from that animal may be sold or eaten, as stated on the product label.'),
  ('Who do you tell about a suspected notifiable animal disease?', 'The veterinary authority, at once.'),
  ('What does a soil pH of 5.2 tell you for a crop needing 6.0?', 'The soil is too acid and liming is likely needed, as advised by the test.'),
  ('Why compute break-even yield?', 'To see the lowest yield at which variable costs are covered at the expected price, so you can judge how much a poor season or a price fall can hurt.'),
  ('Why keep spray and treatment records?', 'For safety, traceability, inspection and good management.'),
  ('Who confirms support scheme and permit rules?', 'The competent Russian authority and a local adviser.')],
 rubric=[
  ('Planning', 'No calendar or rotation', 'Calendar and 4-year rotation', 'Adjusts plan for weather risk'),
  ('Calculation', 'Errors over 5 percent', 'Quantities and margins within 5 percent', 'Tests price and yield changes'),
  ('Safety and inputs', 'Label rules missed', 'Label rules and storage met', 'Writes a site safety plan'),
  ('Records', 'Records have gaps', 'Complete records across areas', 'Uses records to improve decisions'),
  ('Cash', 'No cash view', 'Monthly cash with reserve', 'Plans financing and bad-year response')],
 ladder=[
  'L1 Basic: can name the main farm tasks of the year and the main hazards.',
  'L2 Awareness: can read a seed packet, a feed label and a simple record sheet, and can explain what each number on them means for a plot or an animal.',
  'L3 Foundation: can calculate seed or feed for a plot or group with help, and can fill in input and health records so that quantities match the budget.',
  'L4 Practitioner: can plan and run a small mixed farm with budget, records and safe input use.',
  'L5 Specialist: can design rotations, rations and herd health plans (with agronomist and veterinary advice).',
  'L6 Advanced: can manage a larger holding or cooperative, hire and train staff and negotiate contracts.',
  'L7 Super expert: can lead regional farm advice, introduce new practice and train others, within the law.'],
 jobs=[
  ('Farm worker', 'Carries out field and animal tasks under instruction with safe practice.'),
  ('Smallholder', 'Runs a family farm with a plan and records.'),
  ('Farm records assistant', 'Keeps input, health and sales records for a farm or cooperative.'),
  ('Cooperative coordinator', 'Pools produce and organises sales and shared equipment.'),
  ('Farm advisor assistant', 'Supports advisers with soil, crop and herd data.')],
 next='Next generic courses: Small Business Finance; Food Safety and Hygiene; Agribusiness and Marketing.'),

dict(
 id='RU-03', title='Metallurgy and Fabrication',
 summary='Understand metals and how they are cut, formed, joined and finished in a fabrication workshop, and plan a small job from drawing to costed, quality-checked part. Workshop safety is part of every lesson.',
 level='L4 Practitioner',
 outcomes=[
  ('Understand', 'Explain the properties of common steels and non-ferrous metals and how heat and working change them.'),
  ('Apply', 'Calculate material weight, cutting lists, nesting and offcut waste for a fabricated part.'),
  ('Analyse', 'Compare cutting, forming and joining methods for a given job on cost, accuracy and risk.'),
  ('Evaluate', 'Judge a weld or fabricated part against the drawing and a quality checklist.'),
  ('Create', 'Build a job pack with drawing review, cutting list, process route, cost estimate and inspection record.')],
 task='Prepare a costed job pack for one fabricated steel part, including a cutting list, process route and inspection record.',
 condition='Individual work over 6 weeks with a drawing, tape and calliper, a calculator and the course templates; practical work only under a qualified supervisor.',
 standard='Weights and cutting list correct to within 2 percent; process route safe and complete; estimate reconciles; 8 of 10 check answers right.',
 who='Workshop assistants, apprentices, small fabricators, maintenance staff and people planning to start a small workshop.',
 req='Basic arithmetic and the ability to read a simple drawing; practical work needs a supervised workshop.',
 safety='Hot work, cutting, grinding, lifting and electrical equipment cause serious injury and fire. Practical work must be done under a trained supervisor with protective equipment, ventilation, fire precautions and safe lifting. Welding of pressure parts, lifting equipment and structural work needs qualified, certified people and inspection under the relevant federal rules and the competent authority. This course gives no legal advice and no substitute for such qualification. Check which licences, certificates and inspections apply with the competent Russian authority and a local adviser.',
 evidence='Evidence products: weight and cutting list, nesting plan, process route, cost estimate, inspection record.',
 modules=[
  ('Metals and their properties', 'Understand', 4,
   'Choice of metal sets strength, weight, corrosion resistance, cost and how a part can be made. A cheap steel that rusts in a wet yard or bends under load costs more in the end than a better grade chosen at the start.',
   ['Compare mild steel, alloy steel, stainless steel, cast iron, aluminium and copper alloys.',
    'Define strength, hardness, toughness and ductility in plain terms.',
    'Explain how heat treatment and cold working change properties.',
    'Read a material certificate and match it to the job.'],
   'Steel has a density of about 7,850 kg/m3; aluminium about 2,700 kg/m3. A 1 m x 1 m x 10 mm plate has a volume of 0.01 m3, so it weighs about 78.5 kg in steel and 27 kg in aluminium. At 85 RUB/kg the steel plate costs 6,672.5 RUB. Check: weight saved by aluminium is 51.5 kg.',
   'Choose a metal for three parts, such as a gate hinge, a food tray and a machine guard, and give reasons for each in two sentences.',
   'All three choices are justified by load, environment and cost, and each weight is calculated correctly to within 2 percent.'),
  ('Reading drawings and measuring', 'Apply', 5,
   'A drawing carries sizes, tolerances, welds and finishes. Measuring correctly is the base of quality, because a part that is wrong by 2 mm may not fit and cannot be used. Always measure twice and record the reading at once.',
   ['Read views, sections, dimensions and weld symbols.',
    'Use tape, rule, square, vernier calliper and level; know each reading error.',
    'Apply tolerance: a part 100 mm +/- 1 mm passes between 99 and 101 mm.',
    'Mark out and check before cutting.'],
   'A bracket is 250 mm long with a +/- 1 mm tolerance. Measured pieces: 249.4, 250.9, 251.4 mm. The limits are 249 to 251 mm. The first two pass, because 249.4 and 250.9 are inside. The third is 1.4 mm over nominal, outside the limit, and fails. Result: 2 pass, 1 fail, a pass rate of 67 percent.',
   'Check five dimensions on a sample part against a drawing, using a tape and a calliper, and record each reading, the tolerance limits and a pass or fail.',
   'All five dimensions are recorded to the nearest 0.1 mm and at least 4 of 5 pass or fail judgements agree with the key.'),
  ('Cutting, nesting and material cost', 'Apply', 5,
   'Material is often the largest cost. Good nesting and cutting lists reduce offcuts, and every percent of waste is money thrown into the scrap bin. Plan the cuts on paper before the first cut is made at the machine.',
   ['Weight = volume x density; use tables for sections and plates.',
    'Prepare a cutting list with part sizes, quantity and kerf allowance.',
    'Nest parts to reduce waste; calculate yield percent.',
    'Compare methods: shear, saw, flame, plasma, laser, abrasive; note accuracy and heat-affected zone.'],
   'A 2,000 x 1,000 mm sheet, 5 mm steel, weighs 78.5 kg. Parts use 1,640,000 mm2 of 2,000,000 mm2 = 82 percent yield. At 85 RUB/kg the sheet costs 6,672.5 RUB and waste is 1,201 RUB.',
   'Make a cutting list and a nesting plan for ten parts on one sheet, allow a kerf for each cut, and compute the yield percent and the cost of the waste.',
   'Yield and cost are within 2 percent of the mentor key, and the nesting plan shows every part with its size and quantity.'),
  ('Forming and bending', 'Apply', 4,
   'Bending, rolling and pressing change shape without removing material. Springback, minimum radius and grain direction matter, and a bend that is too tight can crack the part. Test every new setup on an offcut of the same thickness first.',
   ['Estimate bend allowance from thickness and radius.',
    'Respect minimum bend radius to avoid cracking.',
    'Allow springback and test on offcuts.',
    'Choose tooling to suit thickness and length.'],
   'Bending 3 mm sheet to 90 degrees with 3 mm inside radius; bend allowance is about pi x (R + K x t) x 90/180 with K near 0.33: 3.14 x (3 + 1) / 2 = 6.3 mm. A channel has two such bends, so the bend allowances total 2 x 6.3 = 12.6 mm; add them to the three straight lengths (for example 20 + 50 + 20 = 90 mm) to get a flat length of 102.6 mm, to be proved on an offcut.',
   'Calculate the flat length for a two-bend channel of 3 mm sheet from the leg sizes and the bend allowance, then bend an offcut under supervision and compare.',
   'Flat length is within 1 mm of the key and the test bend on the offcut is within 1.5 mm of the calculated size.'),
  ('Joining: welding, bolting and finishing', 'Analyse', 5,
   'Joining choices change strength, cost and inspection need. Welding needs trained, qualified people, and a bolted joint is often safer and cheaper for a beginner shop than a weld on a part that carries load.',
   ['Compare MMA, MIG/MAG, TIG and spot welding, bolts and rivets.',
    'Explain distortion, preheat, filler choice and joint preparation in plain terms.',
    'List typical weld faults: porosity, lack of fusion, undercut, cracks.',
    'Choose finishes: paint, galvanising, powder coat; prepare surfaces.'],
   'A frame has 12 m of fillet weld at 6 mm leg. Time at 3 m/hour = 4 hours. At 400 RUB/hour labour the weld cost is 4 x 400 = 1,600 RUB. Add consumables of 250 RUB for wire and gas: total 1,850 RUB. Check: 12 / 3 = 4 hours, and the total is 1,850 RUB, or about 154 RUB per metre of weld.',
   'Pick a joining method for three jobs, such as a garden gate, a shelf bracket and a pressure vessel, and state the inspection and qualification needed for each.',
   'Each method fits the job, the qualification need is stated, and the pressure vessel is correctly marked as work for certified people only.'),
  ('Workshop safety and hot work', 'Evaluate', 5,
   'Safety is a condition of work. Most injuries come from lifting, cuts, burns, eyes, noise, fumes and electricity. A short check before every task, and the right protective gear worn from start to finish, prevents most of them.',
   ['List protective equipment per task: eyes, face, hearing, hands, feet, respiratory.',
    'Control hot work: clear combustibles, fire watch, extinguisher, permit if required.',
    'Lift safely: weight limits, slings, crane signals, no work under load.',
    'Keep guards on machines, isolate before maintenance.'],
   'Hot work near 20 litres of solvent: the permit stops the job until the solvent is moved 11 m away and a fire watch is set for 30 minutes after work. Check: if the job ends at 14:00, the fire watch lasts until 14:30. Cost of a 20 minute delay to move the solvent is small against the loss of a workshop.',
   'Complete a risk assessment for one task, such as grinding a plate, listing at least five hazards, the control for each and the named person responsible.',
   'At least five hazards are listed, each has a control that works, and one responsible person and an emergency step are named.'),
  ('Inspection and quality records', 'Evaluate', 4,
   'Inspection proves the part matches the drawing and standard. Records protect both customer and workshop, and show a buyer exactly what was checked, by whom and when. Without records a dispute is only one word against another.',
   ['Visual check, dimensional check and, where needed, non-destructive tests by qualified staff.',
    'Record material batch, welder, date and result.',
    'Control non-conforming parts: tag, separate, decide rework or scrap.',
    'Calibrate measuring tools on a schedule.'],
   'Of 50 parts, 3 fail dimensional check: a reject rate of 6 percent. At 1,200 RUB per part, rework of 3 parts at 300 RUB costs 900 RUB. The 50 parts are worth 60,000 RUB, so rework is 1.5 percent of value. If the 3 were scrapped instead, the loss is 3,600 RUB. Check: 3 / 50 = 0.06.',
   'Prepare an inspection sheet with columns for batch, dimension, reading, limit and result, then judge ten sample parts and tag any that fail.',
   'Sheet records every check; judgements agree with the key for at least 9 of 10 parts, and failed parts are tagged and separated.'),
  ('Job pack and costing', 'Create', 4,
   'A quote joins material, labour, machine time, finish and margin. A missing line, such as transport or a change request, turns an apparent profit into a loss, so list every cost before naming a price.',
   ['Total material cost with waste allowance.',
    'Estimate labour hours per operation.',
    'Add machine, consumables, finish, transport and overhead.',
    'Quote a price and check margin; agree changes in writing.'],
   'Material 6,672 RUB, labour 8 h x 400 = 3,200 RUB, consumables 600 RUB, finish 1,500 RUB, overhead 15 percent of 11,972 = 1,796 RUB. Cost 13,768 RUB. A 20 percent margin gives a quote of 16,522 RUB. Check: 11,972 + 1,796 = 13,768; 13,768 x 1.2 = 16,521.6. Profit is 2,754 RUB, which is 16.7 percent of the price.',
   'Build a complete job pack for one part with the drawing review, cutting list, process route, cost estimate, quote and inspection sheet in one folder.',
   'Pack is consistent from drawing to quote, every arithmetic line is within 2 percent of the key, and the safety limits are stated.')],
 quiz=[
  ('What is the approximate density of steel?', 'About 7,850 kg/m3.'),
  ('How do you find plate weight?', 'Volume times density.'),
  ('What is kerf?', 'The width of material removed by the cut itself, which must be added between parts in a cutting list so that each finished piece comes out at the right size.'),
  ('What is springback?', 'The partial return of a bent part toward its original shape after the force is released, so the bend is made slightly past the target angle and tested on an offcut.'),
  ('Name two common weld faults.', 'For example porosity and lack of fusion (or undercut, cracks).'),
  ('Who may weld pressure or lifting parts?', 'Only qualified, certified people working under the relevant federal rules, with inspection by the competent authority; a learner never does this work.'),
  ('What must be cleared before hot work?', 'Combustibles, with a fire watch and an extinguisher ready.'),
  ('A part is 250 mm +/- 1 mm. It measures 251.4 mm. Pass or fail?', 'Fail; it is outside the tolerance.'),
  ('Why calibrate measuring tools?', 'So readings can be trusted, because a worn or dropped calliper gives wrong sizes and wrong pass or fail decisions; calibrate on a set schedule and record the date.'),
  ('What do you do with a non-conforming part?', 'Tag and separate it so it cannot be shipped by mistake, then record the fault and decide rework or scrap with the supervisor.')],
 rubric=[
  ('Calculation', 'Weights or lists wrong', 'Weights, nesting and yield within 2 percent', 'Optimises nesting and cost'),
  ('Process choice', 'Methods unsuitable', 'Methods fit job and qualification limits stated', 'Compares alternatives with costs'),
  ('Safety', 'Hazards missed', 'Hazards, controls and owner stated', 'Adds permits and emergency plan'),
  ('Inspection', 'No records', 'Inspection sheet and non-conformance steps', 'Trends rejects and acts'),
  ('Quote', 'Cost incomplete', 'Cost and margin reconcile', 'Includes risk and change control')],
 ladder=[
  'L1 Basic: can name common metals and workshop hazards and wear the right protective equipment.',
  'L2 Awareness: can read simple dimensions and use a tape and square, and can say whether a measured part is inside or outside its tolerance.',
  'L3 Foundation: can make a cutting list and weight estimate with help, and can state the yield percent and the cost of the waste for a sheet.',
  'L4 Practitioner: can prepare a costed job pack and check a part against a drawing under supervision.',
  'L5 Specialist: can plan fabrication routes and inspection for complex jobs (certified welders and inspectors needed for regulated work).',
  'L6 Advanced: can run a workshop, schedule jobs and manage quality systems.',
  'L7 Super expert: can lead engineering practice, design for manufacture and train others, within the rules.'],
 jobs=[
  ('Fabrication assistant', 'Cuts, fits and finishes parts under supervision.'),
  ('Welder trainee', 'Learns welding under a qualified supervisor towards certification.'),
  ('Quality checker', 'Measures and records parts against drawings.'),
  ('Estimator assistant', 'Builds cutting lists and cost estimates.'),
  ('Small workshop owner', 'Runs a lawful workshop with safety and quality systems.')],
 next='Next generic courses: Workplace Safety; Reading Technical Drawings; Small Business Finance.'),

dict(
 id='RU-04', title='Garments and Accessories',
 summary='Plan, make or source and sell garments and accessories as a small business: design brief, fabric and trim, pattern and fit, costing per item, quality control, labelling and sales channels.',
 level='L4 Practitioner',
 outcomes=[
  ('Understand', 'Explain how a garment or accessory moves from idea to pattern, sample, production and sale.'),
  ('Apply', 'Calculate fabric yardage, cost per item and a retail price for a garment.'),
  ('Analyse', 'Compare make-in-house, outsourced and bought-in options on cost, quality and speed.'),
  ('Evaluate', 'Judge a sample against a quality checklist for stitching, fit and finish.'),
  ('Create', 'Build a small collection plan with specification sheets, costing, quality plan and sales plan.')],
 task='Prepare a small collection plan of three items with specification sheets, costing and quality checks.',
 condition='Individual work over 6 weeks with a measuring tape, a spreadsheet, sample fabrics and trims and the course templates.',
 standard='Fabric and cost calculations correct to within 3 percent; three specification sheets complete; quality checklist applied to two samples; 8 of 10 check answers right.',
 who='Tailors, seamstresses, small label owners, market sellers and people planning to start a garment or accessory business.',
 req='Basic arithmetic. Basic sewing is useful but not required.',
 safety='Garment sale is subject to rules on product labelling, fibre content, safety of children\'s clothing, tax and registration, and consumer rights. This course gives no legal advice. Check which labelling, conformity and registration rules apply to your product with the competent Russian authority and a local adviser. Do not copy protected designs or marks. Machines, irons and cutters cause injury; keep guards, light and ventilation. Earnings vary and none are promised.',
 evidence='Evidence products: design brief, specification sheets, fabric and cost sheet, quality checklist, sales plan.',
 modules=[
  ('From idea to product', 'Understand', 4,
   'A product starts with a customer and a need. The brief ties style, price, size range and season together, and it keeps the maker from spending days on a design that nobody will buy at the planned price.',
   ['Define the customer: age, use, budget, climate.',
    'Write a brief: product, fabric, colours, sizes, target cost and price.',
    'Know the steps: sketch, pattern, sample, fit, grade, cut, sew, finish, pack.',
    'Check if the idea is original and does not copy protected designs.'],
   'A brief for a winter work jacket: price 4,500 RUB, sizes 44 to 56, target cost 2,250 RUB (50 percent), made from 2.2 m of fabric. Check: 50 percent of 4,500 = 2,250 RUB. If fabric at 600 RUB/m takes 2.2 m = 1,320 RUB, then 930 RUB is left for trims, labour and overhead, which must be tested early.',
   'Write a one-page brief for one product, naming the customer, use, climate, size range, fabric, target price and target cost, and check the cost share against the price.',
   'Brief has customer, price, sizes and target cost, and the target cost share is calculated correctly from the price.'),
  ('Fabrics, trims and materials', 'Understand', 4,
   'Fibre, weave, weight and finish decide feel, durability, care and cost. A fabric that looks good on the roll can shrink, fade or pill after a few washes, so always test a swatch before buying a whole batch.',
   ['Compare cotton, linen, wool, synthetics and blends; note weight in g/m2.',
    'Choose lining, interfacing, zips, buttons, thread and labels.',
    'Test shrinkage and colour fastness on a swatch.',
    'Read fibre content and care symbols and keep them for labelling.'],
   'A 10 cm x 10 cm swatch shrinks to 9.5 cm x 10 cm after wash: 5 percent in length. A 2.2 m pattern needs 2.2 / 0.95 = 2.32 m of fabric. At 600 RUB/m the extra 0.12 m costs about 72 RUB per item; on 40 items that is 2,880 RUB, far less than the loss from ruined garments. Check: 0.95 x 2.32 = 2.2.',
   'Test two fabrics for shrinkage by washing a 10 cm x 10 cm swatch of each as per the care label, measure it after drying and compare the results in a table.',
   'Shrinkage is computed correctly to within 0.5 percent, and the fabric allowance for a 2.2 m pattern is adjusted for each fabric.'),
  ('Pattern, fit and sizing', 'Apply', 5,
   'A pattern must fit the target body shapes. Grading creates other sizes from a base size, and a poor base pattern repeats its fit faults in every size. Fix the base size first, on a real person or a form, before grading.',
   ['Take body measurements: bust, waist, hip, length, arm.',
    'Add ease and seam allowance (often 1 cm).',
    'Fit a sample on a person or form and mark changes.',
    'Grade by set steps between sizes; keep a size chart.'],
   'Bust 92 cm with 8 cm ease gives a finished bust of 100 cm; each size step adds 4 cm to the bust, so the next size is 104 cm. The finished bust for the next two sizes is 108 cm and 112 cm. Check: 92 + 8 = 100; 100 + 4 = 104; 104 + 4 = 108; 108 + 4 = 112.',
   'Create a size chart for three sizes with body measurements, ease and finished sizes for bust, waist, hip and length, using a fixed grade step.',
   'Measurements, ease and grade steps are consistent in every row, and each finished size differs from the next by the same step.'),
  ('Fabric use and costing', 'Apply', 5,
   'Cost per item = materials + labour + overhead. Marker efficiency decides fabric waste, so a better layout of the pattern pieces on the cloth saves money on every item made. Keep every cost line in one sheet.',
   ['Lay patterns to cut as little waste as possible; compute marker efficiency.',
    'Add trims, labels, packaging and thread.',
    'Estimate sewing minutes and a labour rate.',
    'Add overhead and a margin to set a price.'],
   'Fabric 2.3 m x 600 RUB/m = 1,380 RUB; trims 220 RUB; labour 90 min at 8 RUB/min = 720 RUB; overhead 150 RUB. Cost 2,470 RUB. At a 40 percent margin on price, price = 2,470 / 0.6 = 4,117 RUB. Check: 40 percent of 4,117 = 1,647, and 4,117 - 1,647 = 2,470. Profit per item is 1,647 RUB, so selling 30 items gives 49,410 RUB before tax.',
   'Cost three items with fabric, trims, labour, overhead and a target margin, then set a price for each item and compare it with the price the customer would pay.',
   'Costs reconcile within 3 percent of the key, every price follows from cost and margin, and one item is flagged if its price is too high.'),
  ('Cutting, sewing and finishing', 'Apply', 5,
   'Order of work and machine setup decide speed and quality. Standard seams and finishes give a clean product, and a sewer who tests tension on a scrap of the same cloth first avoids many ruined pieces. Keep fingers away from the needle and cutter.',
   ['Prepare the machine: needle, tension, stitch length.',
    'Sequence operations to reduce handling.',
    'Finish edges with the right seam; press at each stage.',
    'Keep a daily output and defect count.'],
   'A jacket takes 12 operations of 90 minutes in total. In an 8-hour day (480 min) a sewer completes 5.3 jackets at best; planning for 4.5 allows for rework and breaks. Check: 480 / 90 = 5.33; 4.5 x 90 = 405 min of sewing, leaving 75 min for breaks and rework. A month of 22 days then gives about 99 jackets.',
   'Plan the operations and time for one garment, listing each operation in order with minutes, and compute the daily output for an 8-hour day with breaks.',
   'Sequence is logical, total minutes add up correctly, and the daily output estimate allows at least 10 percent for rework and breaks.'),
  ('Quality control and compliance', 'Evaluate', 5,
   'Quality is checked at cutting, during sewing and at the end. Labelling and safety rules are part of quality, and a defect found at cutting costs far less than one found by a customer after the sale. Record what you find.',
   ['Make an inspection sheet: stitch density, seam strength, symmetry, size, stains, thread ends.',
    'Define acceptable quality level and what to do with defects.',
    'Check labels: size, fibre content, care, maker details as required.',
    'Check children\'s items for small parts, cords and flammability rules with the competent authority.'],
   'In a lot of 100, 6 have defects: 6 percent. If the limit is 3 percent the lot fails; reworking 6 pieces at 120 RUB each costs 720 RUB. After rework to 1 defect in 100, the rate is 1 percent and the lot passes. Check: 6 / 100 = 6 percent, above 3 percent; 1 / 100 = 1 percent, below 3 percent.',
   'Inspect two samples with the checklist, checking stitch density, seams, symmetry, size and stains, and grade each defect as minor or major with a note.',
   'Defects found and graded correctly in at least 8 of 10 checklist items, and the pass or fail result for each sample follows the stated limit.'),
  ('Selling: channels and customers', 'Analyse', 5,
   'Market stalls, shops, online platforms, workshops and corporate orders each have different margin and effort. The best channel is the one that gives the most profit per hour of work, not the one with the highest price.',
   ['Compare channels: price, fees, effort, payment speed.',
    'Take good photos and write honest product descriptions.',
    'Know consumer rights on returns and exchanges.',
    'Set a minimum order and lead time for made-to-order items.'],
   'Sell 50 items at 4,117 RUB direct = 205,850 RUB. Through a shop taking 30 percent you receive 144,095 RUB; the 61,755 RUB difference buys the shop\'s reach and time saved.',
   'Compare two sales channels in a table with price, fee, hours of effort, payment time and risk, then choose one and give reasons in three sentences.',
   'Table has price, fee, effort and payment time for both channels, the net income is calculated correctly, and the choice follows the figures.'),
  ('Collection plan and cash', 'Create', 4,
   'A small collection plan keeps range, cash and workload in balance. A few styles made well and sold fast give cash to buy the next batch; a large range of slow items ties up money in stock for months.',
   ['Limit styles; reuse fabrics across items.',
    'Plan production batches by cash available.',
    'Track stock turn and mark down slow items.',
    'Review sales every month.'],
   'Batch of 30 jackets costs 74,100 RUB. Selling 20 at full price brings 82,340 RUB; the other 10 at 20 percent off bring 32,936 RUB, so the batch ends with 41,176 RUB over cost. Check: 82,340 + 32,936 = 115,276; 115,276 - 74,100 = 41,176. The batch earns 55.6 percent on its cost, if all 30 jackets sell.',
   'Present the three-item collection plan with a specification sheet, a cost sheet, a quality plan and a cash view for the first batch of each item.',
   'Plan has specs, costs, quality plan and a cash view, the batch figures reconcile within 3 percent, and one mark-down rule is stated.')],
 quiz=[
  ('What is ease?', 'Extra room added to body measurements for comfort and movement, such as 8 cm on a bust of 92 cm, so the finished garment is not tight and can be worn freely.'),
  ('How does shrinkage change fabric need?', 'Divide the length by the shrink factor to add allowance.'),
  ('What is marker efficiency?', 'The share of the fabric area covered by pattern pieces; if pieces use 1.9 m2 of 2.3 m2 laid out, efficiency is about 83 percent and the rest is waste.'),
  ('Name three parts of cost per item.', 'Materials, labour and overhead.'),
  ('What is a specification sheet?', 'A document with sizes, fabric, trims, seams and finish for a product.'),
  ('Why test colour fastness?', 'To avoid colour running in wash or wear, which could stain other clothes or the wearer and lead to returns; test a swatch with water and rubbing before buying a whole batch.'),
  ('What labels might be required?', 'Size, fibre content, care and maker details; check with the competent authority.'),
  ('Why avoid copying protected designs?', 'It can break the law, bring claims and fines, and harm the maker whose work was copied; make original designs or use free ones with permission.'),
  ('How do you set a price from cost and margin?', 'Divide cost by one minus the margin share; for a cost of 2,470 RUB and a 40 percent margin, the price is 2,470 / 0.6, about 4,117 RUB.'),
  ('Why track defects by operation?', 'To find and fix the step that causes them, such as wrong tension at the collar, so the same fault stops repeating and rework cost falls over the next batches.')],
 rubric=[
  ('Brief and spec', 'Missing details', 'Complete brief and spec sheet', 'Spec ready for outside makers'),
  ('Costing', 'Cost missing parts', 'Cost and price within 3 percent', 'Tests price and batch size'),
  ('Quality', 'No checks', 'Checklist applied with grades', 'Traces defects to cause'),
  ('Compliance', 'Labels ignored', 'Labels and safety rules listed and confirmed', 'Prepares a compliance file'),
  ('Sales and cash', 'No channel plan', 'Channels compared and cash planned', 'Plans mark-downs and reorder')],
 ladder=[
  'L1 Basic: can name common fabrics and tools and handle a needle and scissors safely.',
  'L2 Awareness: can read a size chart and a care label, and can say which size suits a given set of body measurements with a stated ease.',
  'L3 Foundation: can calculate fabric need and cost for a simple item with help, including a shrinkage allowance, and can set a price from the cost and margin.',
  'L4 Practitioner: can plan, cost, check and sell a small range lawfully.',
  'L5 Specialist: can develop patterns, manage outsourced makers and set quality limits, and can write a specification sheet that an outside maker can follow without questions.',
  'L6 Advanced: can lead a label, plan seasons and manage staff and suppliers.',
  'L7 Super expert: can shape product, sourcing and training for a region, with respect for ethics and law.'],
 jobs=[
  ('Sewing machinist', 'Sews garments or accessories to a specification.'),
  ('Pattern assistant', 'Draws and grades patterns under direction.'),
  ('Quality inspector', 'Checks finished items against a checklist.'),
  ('Market seller', 'Sells garments and accessories to customers.'),
  ('Small label owner', 'Runs a small, lawful garment or accessory business.')],
 next='Next generic courses: Small Business Finance; Retail and Customer Service; Online Selling.'),

dict(
 id='RU-05', title='Restaurants',
 summary='Plan and run a small restaurant or cafe: concept, menu and recipe costing, kitchen and hygiene systems, staff and service, purchasing and cash control, and the permits and inspections that apply.',
 level='L4 Practitioner',
 outcomes=[
  ('Understand', 'Explain how concept, location, menu and service fit together in a restaurant.'),
  ('Apply', 'Calculate recipe cost, menu price and food cost percent for a dish.'),
  ('Analyse', 'Compare menu items on contribution and popularity to improve the menu.'),
  ('Evaluate', 'Judge a kitchen against a food-safety and hygiene checklist.'),
  ('Create', 'Build an opening plan with menu, costings, hygiene system, staffing plan and daily cash report.')],
 task='Prepare a restaurant opening plan with a costed menu, a hygiene system and a daily control sheet.',
 condition='Individual work over 6 weeks with a spreadsheet, a kitchen scale, a probe thermometer and the course templates.',
 standard='Recipe costs correct to within 2 percent; hygiene checklist with 15 or more points and corrective actions; daily sheet reconciles; 8 of 10 check answers right.',
 who='Cooks, waiters, cafe owners, catering staff and people planning to open a restaurant or cafe.',
 req='Basic arithmetic. Kitchen experience helps but is not required.',
 safety='Food service is strictly regulated: premises approval, food hygiene and staff health checks, allergen information, alcohol licensing where relevant, fire safety, waste handling, tax and registration. This course does not give legal advice. Before opening, confirm every permit and inspection with the competent Russian authority and a local adviser. Kitchens have burn, cut, slip and fire hazards; train staff and keep extinguishers and first aid ready. Restaurants fail often; no profit is promised.',
 evidence='Evidence products: concept sheet, costed recipes, menu analysis, hygiene checklist, staff rota, daily control sheet.',
 modules=[
  ('Concept and location', 'Understand', 4,
   'A clear concept names who you serve, what you offer, at what price and where.',
   ['Describe the customer and the occasion: quick lunch, family meal, evening out.',
    'Count passers-by and competitors at the chosen place on different days.',
    'Estimate seats, turns per day and average spend.',
    'Check premises for ventilation, drains, fire exits and approval.'],
   'Step 1: take seats and turns from your passer-by count. 30 seats x 2 turns x 400 RUB average spend = 24,000 RUB per day at full use. Step 2: apply a realistic use of 60 percent, so sales are 14,400 RUB. Step 3: take food at 32 percent, 4,608 RUB, and daily fixed costs of 9,000 RUB, leaving 792 RUB. Check: 24,000 x 0.60 = 14,400 and 14,400 x 0.32 = 4,608, so the margin is thin.',
   'Write a one-page concept and a seat-turn-spend estimate for full use, 60 percent use and 40 percent use, and name the main risk and one test.',
   'Concept names customer, occasion, price and place; all three estimates are arithmetically right; at least one risk and one low-cost test, such as a 3-day passer-by count, are stated.'),
  ('Menu design and recipe costing', 'Apply', 5,
   'Each dish needs a standard recipe, a yield and a cost. Menu price follows cost and market.',
   ['Write a standard recipe with weights and portion size.',
    'Cost each ingredient per portion including trim loss.',
    'Target food cost of 30 to 35 percent of selling price for many menus; test against the market.',
    'Keep the menu short to reduce waste and speed service.'],
   'Soup: 300 g vegetables at 60 RUB/kg = 18 RUB; meat 80 g at 500 RUB/kg = 40 RUB; others 12 RUB. Cost 70 RUB. At a 30 percent food cost, price = 70 / 0.30 = 233 RUB, rounded to 240 RUB. Check: 70 / 240 = 29.2 percent, inside the target. If rivals force a price of 220 RUB, food cost is 70 / 220 = 31.8 percent, still inside 30 to 35 percent.',
   'Cost five dishes from written standard recipes, set a price for each, and test every price against two nearby competitors.',
   'Every recipe cost is within 2 percent of a recheck; each price gives a food cost of 30 to 35 percent or the gap is explained; prices are rounded to the nearest 10 RUB.'),
  ('Menu analysis', 'Analyse', 4,
   'Sort dishes by popularity and contribution margin to decide what to promote, reprice or drop.',
   ['Contribution = price minus food cost per portion.',
    'Rank dishes by number sold and by contribution.',
    'Classify as keep, promote, rework or drop.',
    'Re-check after one month.'],
   'Dish A: price 240, cost 70, contribution 170 RUB, 100 sold = 17,000 RUB. Dish B: price 400, cost 180, contribution 220 RUB, 30 sold = 6,600 RUB. A earns more in total though B has a higher margin per plate. Together they give 23,600 RUB, and A is 72 percent of it. Action: promote B on the menu; if it sells 10 more plates, gain 10 x 220 = 2,200 RUB. Recheck after one month.',
   'Analyse a five-dish sales sample, rank dishes by units and by total contribution, and assign keep, promote, rework or drop to each with a reason.',
   'All five contributions and totals are correct; every dish has one action and a reason in one sentence; at least one change has a numeric target and a recheck date.'),
  ('Food safety and hygiene', 'Evaluate', 6,
   'Food safety controls are built around temperature, time, cleanliness and separation.',
   ['Keep cold food at 5 degrees C or below and hot holding at 63 degrees C or above; cook to a safe core temperature.',
    'Separate raw and cooked foods and use colour-coded boards.',
    'Wash hands, wear clean clothing and stay off work when ill.',
    'Keep cleaning schedules, temperature logs and supplier documents; list allergens on the menu.'],
   'A fridge reads 9 degrees C at 08:00 against a 5 degrees C limit. Stock worth 18,000 RUB is checked with a probe: items above the limit more than 4 hours are discarded; the fault is logged and repaired. If one third was exposed too long, the loss is 18,000 / 3 = 6,000 RUB and 12,000 RUB is kept. Check: the log shows time, reading, action and initials, and a recheck after repair reads 4 degrees C.',
   'Run a hygiene audit with a 15-point checklist covering temperature, separation, hands, cleaning, allergens and records, and write an action for each fault.',
   'At least 15 points are checked with a pass or fail; every fault is graded and has an action, an owner and a date; the temperature log has no gaps over one week.'),
  ('Purchasing and stock', 'Apply', 4,
   'Order from par levels, check deliveries and rotate stock to reduce waste.',
   ['Set par levels for each item from average use.',
    'Check temperature, quantity and quality on delivery.',
    'Store first in, first out with date labels.',
    'Count stock weekly and compute actual food cost.'],
   'Opening stock 40,000 RUB + purchases 120,000 RUB - closing stock 38,000 RUB = 122,000 RUB food used. Food sales 380,000 RUB, so food cost is 32.1 percent. Against a 30 percent target, food should be 0.30 x 380,000 = 114,000 RUB, so the excess is 8,000 RUB. Check causes: waste, over-portioning, unrecorded staff meals and prices. Count again next week.',
   'Compute weekly food cost from two stock counts and the purchase invoices, compare it with the target, and list likely causes of any gap.',
   'Food used and food cost percent are correct to one decimal place; the gap in RUB is shown; at least three causes are listed and one is chosen for a fix with a date.'),
  ('Kitchen flow and service', 'Apply', 4,
   'A good flow cuts waits and mistakes: prep, cook, pass, serve, clear.',
   ['Set mise en place before service.',
    'Write order tickets clearly with table, items and allergies.',
    'Set target times: starter in 8 minutes, main in 18 minutes.',
    'Brief staff before and review after service.'],
   'A table of four orders at 19:10; starters are due at 19:18 (8 minutes) and mains by 19:28 (18 minutes). A main served at 19:35 is 7 minutes late and the cause, such as a missing sauce, is logged. Check: if 3 of 20 tickets are late, 3 / 20 = 15 percent, above a 10 percent limit, so the pass is reviewed and prep is changed before the next service.',
   'Draw a service flow from order to clearing with a time target at each stage, and a ticket layout that shows table, items and allergies.',
   'The flow has at least five stages with a target time each; the ticket shows allergies in a fixed place; a sample of 10 tickets is timed and the late share is calculated.'),
  ('People, law and money', 'Evaluate', 5,
   'Staff, permits and cash control hold the business up.',
   ['Plan staffing from busy hours and labour cost percent.',
    'Keep staff training and health records as required.',
    'Reconcile till takes with the daily sales report.',
    'Confirm permits, inspections and alcohol rules with the competent authority.'],
   'Weekly sales 380,000 RUB; labour 114,000 RUB = 30 percent; food 122,000 RUB = 32 percent; so food plus labour is 62 percent, leaving 38 percent for rent, energy and other costs and margin. Check: 380,000 - 114,000 - 122,000 = 144,000 RUB. If rent is 60,000, energy 30,000 and other costs 24,000 RUB, that is 114,000 RUB and 30,000 RUB remains, about 8 percent of sales.',
   'Build a weekly profit-and-loss sketch with sales, food, labour, rent, energy, other costs and margin, each in RUB and percent, and reconcile it to the till report.',
   'Every line is in RUB and percent; lines add up to sales; till takes match the daily report within 1 percent or the difference is explained; permits and records are listed with who confirms them.'),
  ('Opening plan and review', 'Create', 4,
   'The plan joins concept, menu, safety and cash and sets a review rhythm.',
   ['List opening costs, equipment and working cash.',
    'Plan a soft opening with limited menu.',
    'Set daily, weekly and monthly checks.',
    'Prepare for inspection day.'],
   'Setup cost 1,800,000 RUB and monthly fixed costs 260,000 RUB; with a contribution of 60 percent of sales, break-even sales are 260,000 / 0.60 = 433,333 RUB per month, about 14,444 RUB per day over 30 days. At sales of 520,000 RUB, contribution is 312,000 RUB, profit 52,000 RUB, and setup pays back in 1,800,000 / 52,000 = about 35 months, so sales must rise or setup cost fall.',
   'Present the opening plan with setup costs, working cash, soft-opening menu, break-even, payback and the daily, weekly and monthly checks.',
   'Break-even and payback are correct; working cash covers at least 3 months of fixed costs or the gap is stated; the check list has owners; every permit is marked confirmed or pending.')],
 quiz=[
  ('What is food cost percent?', 'Food cost divided by food sales, times 100.'),
  ('What cold-holding temperature is expected?', 'Five degrees C or below.'),
  ('What is a par level?', 'The target stock level for each item used to decide orders.'),
  ('Why use colour-coded boards?', 'To keep raw and cooked foods apart.'),
  ('How is contribution margin found?', 'Selling price minus food cost per portion.'),
  ('What do you do when a fridge is above its limit?', 'Check and discard unsafe stock, log the fault and repair it.'),
  ('Why list allergens?', 'To protect customers with allergies, as the rules require.'),
  ('What is break-even sales?', 'Fixed costs divided by contribution share of sales.'),
  ('Who confirms permits for a restaurant?', 'The competent Russian authority and a local adviser.'),
  ('Why keep temperature logs?', 'To prove safe handling and spot faults early.')],
 rubric=[
  ('Costing', 'Missing costs', 'Recipe cost and prices within 2 percent', 'Tests prices against competitors'),
  ('Hygiene', 'Few points checked', 'Checklist of 15 or more with actions', 'Runs a staff training session'),
  ('Menu analysis', 'No analysis', 'Contribution and popularity ranking', 'Redesigns menu with forecast'),
  ('Control', 'Cash not reconciled', 'Daily sheet reconciles', 'Finds and fixes variance'),
  ('Plan', 'No break-even', 'Break-even and opening plan consistent', 'Includes risk and review plan')],
 ladder=[
  'L1 Basic: can wash hands properly, name basic kitchen hazards and follow a recipe.',
  'L2 Awareness: can explain temperature limits and read a menu with allergens.',
  'L3 Foundation: can cost a simple recipe and keep a temperature log.',
  'L4 Practitioner: can run a small cafe kitchen or floor with costing, hygiene and daily control.',
  'L5 Specialist: can design menus, train staff and manage supplier contracts.',
  'L6 Advanced: can run a restaurant business with budgets, audits and several staff.',
  'L7 Super expert: can lead multi-site operations and standards, and teach others, within the law.'],
 jobs=[
  ('Kitchen assistant', 'Prepares ingredients and keeps the kitchen clean and safe.'),
  ('Line cook', 'Cooks to recipe and portion standards.'),
  ('Waiter', 'Serves guests, takes orders and handles payments.'),
  ('Cafe supervisor', 'Runs a shift, stock counts and daily reports.'),
  ('Small restaurant owner', 'Runs a lawful restaurant with costing and control.')],
 next='Next generic courses: Food Safety and Hygiene; Hospitality Service; Small Business Finance.'),

dict(
 id='RU-06', title='Educational Advisory Services',
 summary='Set up and deliver an honest educational advisory service: understand learners and their goals, map pathways and entry rules, give clear unbiased guidance, protect personal data and keep sound records.',
 level='L4 Practitioner',
 outcomes=[
  ('Understand', 'Explain the main education pathways, entry steps and the role of an adviser.'),
  ('Apply', 'Conduct a structured guidance interview and record agreed actions.'),
  ('Analyse', 'Compare study options on fit, entry requirements, time, cost and risk.'),
  ('Evaluate', 'Judge an information source or offer for accuracy and honesty.'),
  ('Create', 'Build an advisory service pack with intake form, option sheet, action plan and data protection note.')],
 task='Deliver a documented guidance session and produce an option comparison and an action plan for a learner case.',
 condition='Individual and peer work over 6 weeks using case studies, interview templates and a spreadsheet; no real personal data is used in training.',
 standard='Interview covers goals, strengths, constraints and options; comparison has at least 3 options and 5 criteria; plan has dated actions; 8 of 10 check answers right.',
 who='Teachers, career advisers, school and college staff, training centre staff and people planning an advisory service.',
 req='Good communication; no formal qualification is required for the course.',
 safety='Education services are regulated: institutions and programmes may need licences or accreditation, and advice about study abroad, recognition of qualifications and visas depends on current rules. An adviser must not promise admission, results, jobs or visas, and must not take hidden commissions without telling the learner. Personal data of learners, especially children, must be protected under the relevant federal rules. This course gives no legal advice. Confirm licensing, data and advertising rules with the competent Russian authority and a local adviser.',
 evidence='Evidence products: intake form, interview record, option comparison, action plan, data protection note, follow-up log.',
 modules=[
  ('The adviser role and ethics', 'Understand', 4,
   'An adviser helps a learner decide; the learner owns the decision. Honesty and independence are the core duties.',
   ['State what you can and cannot do: inform, guide, refer; not guarantee.',
    'Declare any payment from a school or provider.',
    'Respect confidentiality and its limits, such as risk of harm.',
    'Refer to specialists for needs beyond your skills.'],
   'A learner asks, "Will I get in?" A clear answer: "I cannot promise that. Last year 120 applied for 40 places, so about 1 in 3; here is how to raise your chances." Check: 40 / 120 = 0.33. Then name two steps, such as improving a weak subject by the next test and preparing a back-up option, and note in the record that no promise was made and that no payment from any provider was involved.',
   'Write a one-page code of practice with at least six rules, and add two sample answers to common learner questions that avoid any promise.',
   'The code covers honesty, payment disclosure, confidentiality with its limits, and referral; at least six rules are written in plain words; both sample answers give a real figure and no guarantee.'),
  ('Education pathways and entry rules', 'Understand', 5,
   'Learners move through stages: general education, vocational training, higher education and adult learning. Each has entry steps and dates.',
   ['Draw the pathway map with ages, qualifications and links between stages.',
    'List entry routes: exams, tests, interviews, portfolios, prior learning.',
    'Note key dates and documents for applications.',
    'Check current rules with the official body before advising, since they change.'],
   'A school leaver has 70 of 100 points against an entry line of 65, with 3 places per 10 applicants. Margin = 70 - 65 = 5 points, which is thin because last year the line moved by 4 points. Step 1: confirm the current line with the official body. Step 2: list two back-up courses with lower lines. Check: with 30 percent of applicants admitted, a back-up option is needed.',
   'Build a pathway map for one region showing stages, ages, entry routes, key dates and the official body that confirms each rule.',
   'The map has at least four stages and three entry routes; every rule has a named verification source and a check date; two common learner journeys are traced on it from start to entry.'),
  ('Guidance interview', 'Apply', 5,
   'A good interview moves from rapport to goals, strengths, constraints, options and actions.',
   ['Open with purpose, time and confidentiality.',
    'Use open questions and listen without leading the learner.',
    'Summarise back and check understanding.',
    'Agree 2 to 3 actions with dates.'],
   'In a 45-minute session: 5 minutes opening, 20 minutes exploring, 10 minutes options, 10 minutes actions. Check: 5 + 20 + 10 + 10 = 45. Two actions: collect results by Friday; visit two programmes next week. The adviser asks mostly open questions, summarises twice, and the learner, not the adviser, states the final choice of next steps in the record.',
   'Run a 45-minute role-play interview with a peer observer and record it on the interview template, including a summary and two dated actions.',
   'Timing stays within 5 minutes of plan; at least eight open questions are used; the record shows goals, strengths, constraints, options and two actions, each with a date and an owner.'),
  ('Assessing needs and strengths', 'Analyse', 4,
   'Interests, strengths, values and constraints (money, location, health, family) all shape choices.',
   ['Use simple tools: interest list, skills list, values ranking.',
    'Collect evidence such as grades and projects.',
    'Spot barriers early: distance, cost, language, disability support.',
    'Record only data needed for the advice.'],
   'Budget for study: tuition 90,000 RUB, living 12,000 RUB x 10 months = 120,000 RUB, total 210,000 RUB per year against family support of 150,000 RUB; the gap is 60,000 RUB and options must address it. Check: 90,000 + 120,000 = 210,000 and 210,000 - 150,000 = 60,000, or 5,000 RUB a month over 12 months. Options include a cheaper programme, part-time work or a local course.',
   'Complete a needs profile for a case covering interests, strengths, values, constraints and a yearly budget with the gap in RUB.',
   'The profile lists at least three strengths with evidence and three constraints; the budget adds up; the gap is stated in RUB per year and per month; only data needed for the advice is recorded.'),
  ('Comparing options', 'Analyse', 5,
   'Compare at least three options against the same criteria and show the trade-offs.',
   ['Choose criteria: fit, entry chance, length, cost, location, outcomes.',
    'Weight criteria by the learner\'s priorities.',
    'Score and total; test the result by changing weights.',
    'Discuss the risks of each option.'],
   'Weights: fit 40, cost 30, entry chance 30. Option A scores 8, 6, 7; total = 3.2 + 1.8 + 2.1 = 7.1. Option B scores 7, 8, 5; total = 2.8 + 2.4 + 1.5 = 6.7. A is slightly ahead. Test: if cost weight rises to 40 and fit falls to 30, A = 2.4 + 2.4 + 2.1 = 6.9 and B = 2.1 + 3.2 + 1.5 = 6.8, so the lead is fragile and risks must be discussed.',
   'Build a weighted comparison table with three options, five criteria and weights from the learner, then change the weights once and report what changes.',
   'Weights sum to 100; every total is correct to one decimal place; the sensitivity test is shown; a risk is stated for each option; the learner, not the adviser, picks the final weights.'),
  ('Checking information and avoiding misleading claims', 'Evaluate', 4,
   'Advice is only as good as its sources. Offers that promise results are a warning sign.',
   ['Check licence and accreditation of a provider through the competent body.',
    'Ask for outcome data and its method.',
    'Spot pressure tactics, guarantees and vague fees.',
    'Keep a source log with date of check.'],
   'A provider claims "100 percent of graduates get jobs" with no data. You request the numbers: of 60 graduates 48 answered a survey and 36 had a job, which is 75 percent of respondents and 60 percent of graduates. Check: 36 / 48 = 0.75 and 36 / 60 = 0.60. The claim is not supported; note the response rate of 80 percent (48 / 60) and ask how a job was defined and when it was counted.',
   'Judge three provider claims by asking for licence status, outcome data and method, and rate each claim as supported, partly supported or unsupported.',
   'Each rating cites at least two pieces of evidence; the source log gives name, date checked and result; one pressure tactic or vague fee is found and described in the notes.'),
  ('Data protection and records', 'Apply', 4,
   'Learner data is personal and often about minors. Collect little, store safely and share only with consent.',
   ['Explain the purpose and get consent before recording.',
    'Store files in a locked place or protected system.',
    'Keep records for a set time and then delete them.',
    'Check the relevant federal rules with the competent authority.'],
   'A service holds 400 files; if 25 percent are past the retention period, 100 files must be reviewed and deleted. Check: 400 x 0.25 = 100. At 10 files reviewed per hour the clean-up takes 10 hours, so schedule it in two half-days and record the deletion date in a log. Files of minors are handled first, and consent forms are checked before any sharing.',
   'Draft a data protection note and a retention table that lists each type of record, its purpose, who may see it, where it is kept and when it is deleted.',
   'The note covers purpose, consent, storage, sharing and deletion in under one page; the table has at least five record types, each with a retention period marked as to be confirmed with the competent authority.'),
  ('Service design and follow-up', 'Create', 4,
   'A service has intake, session, plan, follow-up and review.',
   ['Design the client journey in five steps.',
    'Set response times and caseload.',
    'Track outcomes: actions done, places gained, learner feedback.',
    'Plan improvement from the data.'],
   'An adviser sees 6 learners/day x 5 days = 30 sessions/week; with 45 min sessions plus 15 min notes that is 30 hours, so the weekly caseload is capped at 30. Check: 45 + 15 = 60 minutes x 30 = 1,800 minutes = 30 hours. Leaving 10 hours for preparation, follow-up and training in a 40-hour week, the service reviews outcomes monthly and adjusts the cap if feedback or actions done fall.',
   'Present the service pack with the five-step client journey, response times, caseload cap, outcome measures and an improvement plan.',
   'The pack joins intake form, option sheet, action plan, data note and follow-up log; caseload arithmetic is correct; at least three outcome measures have a target and a review date.')],
 quiz=[
  ('Who owns the decision in guidance?', 'The learner owns the decision; the adviser informs, challenges gently, compares options honestly and records what was agreed.'),
  ('May an adviser promise admission?', 'No; an adviser may inform, guide and support with honest figures and options, but admission is decided by the institution, so no guarantee may be given.'),
  ('What must be declared?', 'Any payment or interest from a provider.'),
  ('Why check a provider\'s licence?', 'To confirm it may lawfully offer the programme.'),
  ('What is an open question?', 'One that invites a full answer, not just yes or no.'),
  ('Why agree dated actions?', 'So the learner knows what to do next and progress can be checked.'),
  ('What is a weighted comparison?', 'Scoring options on criteria weighted by the learner\'s priorities.'),
  ('How should learner data be treated?', 'Collected sparingly, stored safely, shared with consent and deleted on time.'),
  ('Why verify entry rules?', 'They change from year to year, and wrong advice about dates or documents can cost the learner a place, so always check the official source.'),
  ('Name one warning sign of a misleading offer.', 'A guaranteed result or pressure to pay quickly.')],
 rubric=[
  ('Ethics', 'Makes promises', 'Honest, discloses interests', 'Handles a conflict of interest well'),
  ('Interview', 'No structure', 'Structured with dated actions', 'Adapts to the learner with skill'),
  ('Options', 'One option only', 'Three options with 5 criteria', 'Tests weights and risks'),
  ('Sources', 'Unchecked claims', 'Sources checked and logged', 'Corrects a poor source'),
  ('Data', 'No protection', 'Consent, storage, retention covered', 'Runs a data audit')],
 ladder=[
  'L1 Basic: can explain the school stages and listen to a learner with respect.',
  'L2 Awareness: can find official information on entry steps.',
  'L3 Foundation: can run a simple guidance conversation with a script.',
  'L4 Practitioner: can run a full guidance session, compare options and write an action plan.',
  'L5 Specialist: can advise on complex pathways and refer to specialists.',
  'L6 Advanced: can lead an advisory team and design the service and quality system.',
  'L7 Super expert: can shape guidance practice and train advisers across a region, within the rules.'],
 jobs=[
  ('Education adviser', 'Guides learners on study options and entry.'),
  ('Admissions assistant', 'Helps learners with applications and documents.'),
  ('Career guidance assistant', 'Supports learners with choices linked to work.'),
  ('Training centre coordinator', 'Matches learners to courses and tracks progress.'),
  ('Independent advisory service owner', 'Runs a lawful, honest advisory service.')],
 next='Next generic courses: Career Launch; Coaching and Mentoring; Customer Service.'),

dict(
 id='RU-07', title='Timber and Furniture',
 summary='Supply, saw and work timber and run a small joinery and furniture business: species and grading, moisture, volume and yield calculations, cutting lists, joinery methods, finishing, costing and legal sourcing.',
 level='L4 Practitioner',
 outcomes=[
  ('Understand', 'Explain timber species, moisture content, drying and how wood moves.'),
  ('Apply', 'Calculate timber volume, sawing yield, cutting lists and cost for a furniture item.'),
  ('Analyse', 'Compare joinery methods and materials on strength, appearance and cost.'),
  ('Evaluate', 'Judge a timber lot or a made piece against grade and quality criteria.'),
  ('Create', 'Build a job pack with a drawing, cutting list, process route, cost and legal sourcing file.')],
 task='Prepare a costed job pack for one furniture item with a cutting list, joinery plan, finish schedule and a legal timber sourcing file.',
 condition='Individual work over 6 weeks with a tape, a moisture meter if available, a calculator and the course templates; practical work only under a trained supervisor.',
 standard='Volumes and cutting list correct to within 2 percent; joinery plan suited to the load; costing reconciles; sourcing file shows origin documents for every board; 8 of 10 check answers right.',
 who='Carpenters, joiners, sawmill and timber yard workers, furniture makers and people planning a wood business.',
 req='Basic arithmetic and the ability to read a simple drawing.',
 safety='Forestry and timber trade are regulated: felling rights, transport and origin documents, timber accounting systems, protected species and areas, and fire rules all apply. Buying or selling timber without proof of lawful origin is unlawful and the stock may be seized. Saws, planers and lifting cause serious injury and dust is a health hazard. This course does not give legal advice. Check which permits, documents and registrations apply with the competent Russian authority and a local adviser. Use trained operators, guards and dust control. No income is promised.',
 evidence='Evidence products: volume and yield sheet, cutting list, joinery plan, finish schedule, cost sheet, sourcing file.',
 modules=[
  ('Timber species and grades', 'Understand', 4,
   'Species and grade decide strength, appearance, workability and price.',
   ['Compare softwoods (pine, spruce, larch) and hardwoods (birch, oak) for use.',
    'Know grading by knots, cracks, wane and straightness.',
    'Match species to use: frame, floor, table top, outdoor.',
    'Describe wood structure: grain, heartwood, sapwood.'],
   'Pine boards graded A cost 24,000 RUB/m3; grade C costs 14,000 RUB/m3. For hidden frame parts, grade C saves 10,000 RUB per m3. Check: 24,000 - 14,000 = 10,000. For a job needing 0.5 m3 of hidden parts the saving is 5,000 RUB, but a visible table top still needs grade A because knots and cracks would show and weaken the surface.',
   'Choose species and grades for three items, such as a frame, a floor and a table top, and give a one-line reason and a price per m3 for each.',
   'Each choice fits the use, load and appearance; each has a reason; the saving or extra cost against grade A is calculated correctly in RUB per m3; no item uses a weak grade for a load-bearing part.'),
  ('Wood supply and legal origin', 'Evaluate', 5,
   'Lawful origin documents are the base of the whole business. Without them stock and money are at risk.',
   ['List documents to ask for: origin, volume, species, transport, seller registration.',
    'Match delivered volume and species to documents.',
    'Never accept timber without a clear chain of papers.',
    'Confirm rules for protected species and for export or transport with the competent authority.'],
   'A load is documented as 12 m3 pine; measured at 14 m3 with some oak. The 2 m3 difference and the species mismatch mean the load is not accepted until the papers are corrected. Check: 14 - 12 = 2 m3, which is 2 / 12 = 16.7 percent over. Step 1: hold the load apart. Step 2: ask the seller for corrected papers. Step 3: log the decision with date and name.',
   'Build a supplier file for one source listing documents required, checks at delivery, a decision rule and a record of each load.',
   'The file lists at least five documents; the rule sets a volume tolerance, for example 2 percent, and rejects any species mismatch; three sample loads are checked and logged; the competent authority is named as the source for rules.'),
  ('Measuring and volume', 'Apply', 4,
   'Volume of sawn timber is length x width x thickness. Round logs use a volume formula and a taper allowance.',
   ['Compute board volume in m3 from mm dimensions.',
    'Compute log volume with the cylinder formula as an estimate.',
    'Count packs and apply a stacking factor.',
    'Record measurement method with each lot.'],
   'Convert mm to m first. A board 3.0 m x 0.150 m x 0.025 m = 0.01125 m3. 80 boards = 0.9 m3; at 20,000 RUB/m3 the lot costs 18,000 RUB. Check: 0.01125 x 80 = 0.9 and 0.9 x 20,000 = 18,000. If the supplier invoices 1.0 m3 for the same lot, the overcharge is 0.1 m3 x 20,000 = 2,000 RUB, so measure every lot at delivery.',
   'Calculate volumes and costs for three lots from measured dimensions and compare each with the invoice.',
   'All three volumes are within 2 percent of a recheck; units are converted correctly; each cost in RUB is shown; any invoice difference above 2 percent is flagged and the measuring method is recorded.'),
  ('Sawing, yield and drying', 'Analyse', 5,
   'Sawing pattern decides yield; drying decides stability.',
   ['Estimate sawn yield from logs; typical yield is 50 to 65 percent.',
    'Allow saw kerf and trim.',
    'Dry to a target moisture content for use: about 8 to 12 percent indoors.',
    'Stack with stickers for airflow and protect from rain and sun.'],
   '2.0 m3 of logs at 55 percent yield gives 1.1 m3 sawn. Logs at 6,000 RUB/m3 cost 12,000 RUB, so sawn timber costs 10,909 RUB/m3 before labour and drying. Check: 2.0 x 0.55 = 1.1 and 12,000 / 1.1 = 10,909. If a better sawing pattern lifts yield to 60 percent, sawn volume is 1.2 m3 and the cost falls to 10,000 RUB/m3, a saving of 909 RUB per m3.',
   'Compute yield and cost per m3 sawn from a log lot, then test one change in sawing pattern and drying plan and report the effect.',
   'Yield and cost per m3 are within 2 percent of a recheck; the comparison shows both patterns; the drying plan states a target moisture of 8 to 12 percent and a stacking method with stickers.'),
  ('Cutting lists and material planning', 'Apply', 5,
   'A cutting list turns a drawing into parts with sizes, grain direction and quantity.',
   ['List parts: name, length, width, thickness, quantity.',
    'Add allowance for planing and trimming.',
    'Nest parts on boards to limit waste.',
    'Compute total board metres and waste percent.'],
   'A table needs 4 legs 720 x 60 x 60 mm, 2 rails 1,100 x 90 x 25, a top 1,200 x 700 x 25. Volumes: legs 0.01037 m3, rails 0.00495 m3, top 0.021 m3; total 0.0363 m3; with 25 percent allowance 0.0454 m3. Check: 0.01037 + 0.00495 + 0.021 = 0.03632, and 0.03632 x 1.25 = 0.0454. Waste is 0.0454 - 0.0363 = 0.0091 m3, which is 20 percent of the purchase.',
   'Prepare a cutting list and a waste figure for a cabinet with part names, sizes in mm, quantities, grain direction and a nesting sketch.',
   'The list is complete against the drawing; volumes and totals are within 2 percent; the allowance is stated; waste percent is calculated; grain direction is marked on every visible part.'),
  ('Joinery and assembly', 'Analyse', 5,
   'Joints must carry the load and allow for wood movement across the grain.',
   ['Compare mortise and tenon, dowel, dovetail, lap, screws and glue.',
    'Allow for seasonal movement in wide panels.',
    'Clamp, glue and dry as instructed; check square.',
    'Test a sample joint for strength by a simple load.'],
   'A solid pine panel 600 mm wide may move about 1 percent across the grain with large humidity change: about 6 mm. Fix with slotted holes. Check: 600 x 0.01 = 6 mm. A slot should allow at least 3 mm each side of the screw, so a fixed top on a cupboard would crack or split the frame. Choose mortise and tenon for chair legs because racking loads act on them.',
   'Choose joints for a chair and a cupboard, give a reason for each joint, and test one sample joint with a simple safe load.',
   'Each joint suits the load and allows for movement across the grain; at least four joint types are compared; the movement figure is calculated; the test load, result and any failure are recorded with eye protection used.'),
  ('Finishing and safety', 'Evaluate', 5,
   'Sanding and finish protect the wood and set appearance. Dust, solvents and machines need control.',
   ['Sand through grits (for example 80, 120, 180).',
    'Compare oil, wax, varnish and paint on durability and care.',
    'Control dust with extraction and masks; keep solvents away from heat.',
    'Guard machines; lock out before blade change; wear hearing and eye protection.'],
   'A varnish covers 10 m2/L per coat; a table with 3 m2 and 3 coats needs 0.9 L. At 700 RUB/L the finish costs 630 RUB. Check: 3 x 3 = 9 m2 of coverage, 9 / 10 = 0.9 L, 0.9 x 700 = 630. Allow drying between coats, sand lightly with 180 grit, and keep solvent rags in a closed metal container away from heat to prevent fire.',
   'Write a finish schedule and risk list covering sanding grits, coats, drying times, quantities in litres and RUB, dust, solvent and machine controls.',
   'The schedule has coats, quantities and cost; at least five risks each have a named control; extraction, masks, hearing and eye protection and lockout are listed; quantities are correct.'),
  ('Costing, pricing and the job pack', 'Create', 4,
   'The job pack joins materials, labour, finish, overhead and margin.',
   ['Compute material cost from the cutting list.',
    'Estimate hours per operation.',
    'Add hardware, finish, delivery and overhead.',
    'Set a price with a margin; agree changes in writing.'],
   'Timber 0.0454 m3 x 20,000 = 908 RUB; hardware 400 RUB; finish 630 RUB; labour 12 h x 350 = 4,200 RUB; overhead 15 percent of 6,138 = 921 RUB. Cost 7,059 RUB. With a 30 percent margin, price = 7,059 / 0.7 = 10,084 RUB. Check: 908 + 400 + 630 + 4,200 = 6,138 and 6,138 + 921 = 7,059; margin = 10,084 - 7,059 = 3,025 RUB, 30 percent of price. Agree any change in writing before work.',
   'Assemble the full job pack with sourcing file, cutting list, finish schedule, costing, price, timeline and a change record.',
   'The pack is consistent across documents; costs add up; price margin is correct; the sourcing file has matched origin papers; a risk list and a written change rule are included.')],
 quiz=[
  ('How is board volume found?', 'Length x width x thickness, in metres.'),
  ('What is a typical indoor moisture target?', 'About 8 to 12 percent.'),
  ('Why must origin papers match the load?', 'Mismatches may show unlawful timber and risk seizure.'),
  ('What is sawing yield?', 'Sawn timber volume divided by log volume, times 100.'),
  ('Why use stickers when stacking?', 'To allow air to flow and dry the boards evenly.'),
  ('What is wood movement?', 'Swelling and shrinking with humidity, mostly across the grain.'),
  ('Name two ways to control dust.', 'Extraction at the machine and masks (also cleaning methods).'),
  ('What is a cutting list?', 'A list of parts with sizes, quantity and grain direction.'),
  ('Who can confirm timber permits?', 'The competent Russian authority and a local adviser.'),
  ('Why add an allowance to the cutting list?', 'For planing, trimming and defects.')],
 rubric=[
  ('Sourcing', 'No papers checked', 'Documents matched to load', 'Builds a supplier audit routine'),
  ('Calculation', 'Errors over 2 percent', 'Volume, yield, cost within 2 percent', 'Optimises yield'),
  ('Joinery', 'Joints unsuitable', 'Joints suit load and movement', 'Tests and improves joints'),
  ('Safety', 'Hazards missed', 'Guards, dust, fire controls', 'Runs a safety review'),
  ('Job pack', 'Incomplete', 'Pack complete and consistent', 'Includes risk and change control')],
 ladder=[
  'L1 Basic: can name common timbers and the main workshop hazards.',
  'L2 Awareness: can read a simple drawing and measure a board.',
  'L3 Foundation: can compute volume and a simple cutting list with help.',
  'L4 Practitioner: can plan and cost a furniture job with lawful sourcing.',
  'L5 Specialist: can design joinery, manage drying and train staff.',
  'L6 Advanced: can run a sawmill or workshop with budgets and audits.',
  'L7 Super expert: can lead sector practice in lawful, sustainable timber use and teach others.'],
 jobs=[
  ('Timber yard assistant', 'Receives, measures and stacks timber with records.'),
  ('Sawmill operator trainee', 'Operates saws under supervision.'),
  ('Joiner', 'Makes frames, doors and furniture to drawings.'),
  ('Furniture finisher', 'Sands and finishes furniture safely.'),
  ('Small workshop owner', 'Runs a lawful wood business.')],
 next='Next generic courses: Workplace Safety; Reading Technical Drawings; Small Business Finance.'),

dict(
 id='RU-08', title='Cooking Gas Distribution',
 summary='Understand the lawful, safe handling and distribution of cooking gas (LPG cylinders and similar supplies): properties, cylinder handling, storage, transport, customer safety, records and the licensing limits. Safety and compliance come first.',
 level='L4 Practitioner',
 outcomes=[
  ('Understand', 'Explain the properties and hazards of liquefied petroleum gas and the layers of control around it.'),
  ('Apply', 'Calculate cylinder fill, cylinder counts, delivery loads and unit margins.'),
  ('Analyse', 'Compare delivery and storage arrangements on safety, cost and customer service.'),
  ('Evaluate', 'Judge a storage area, a vehicle or a customer installation against a safety checklist.'),
  ('Create', 'Build a compliance-first operating plan with checklists, records, an emergency plan and a cost model.')],
 task='Prepare a compliance-first operating plan for a small cooking gas distribution point, with safety checklists, records, an emergency plan and a unit cost model.',
 condition='Desk-based training over 6 weeks using case studies, checklists and a spreadsheet; no handling of gas or cylinders is part of this course.',
 standard='Checklists cover storage, transport, delivery and emergency; unit cost model correct to within 2 percent; plan states each licence or approval to confirm; 9 of 10 check answers right.',
 who='Delivery staff, depot assistants, small distributors, retail staff and people considering this business.',
 req='Basic arithmetic. No prior experience is needed. No practical work with gas is part of the course.',
 safety='Liquefied gas is flammable and can explode; handling, storage, filling, transport and sale are licensed, inspected and strictly regulated under the relevant federal rules, which cover premises, vehicles, equipment, trained and certified staff, cylinder testing and insurance. This course is desk-based awareness and planning, not training to handle gas. Do not fill, repair, move or store cylinders without lawful authority, certified training and the required approvals. Before any step, confirm the licence and rules with the competent Russian authority and a qualified local adviser. In a leak, move people away, avoid sparks and call the emergency service. No income is promised.',
 evidence='Evidence products: hazard table, compliance register, storage and delivery checklists, emergency plan, unit cost model.',
 modules=[
  ('Properties and hazards of LPG', 'Understand', 5,
   'LPG is stored as a liquid under pressure and becomes a heavier-than-air gas on release. It is flammable in a narrow range of mixture with air and can collect in low places.',
   ['Explain why LPG is heavier than air and collects in pits and cellars.',
    'Describe flammable range, ignition sources and why a small leak is serious.',
    'Explain that cylinders must never be filled completely, to allow for liquid expansion.',
    'Name the odorant and why it is added.'],
   'A 50 L cylinder is filled to about 85 percent: 42.5 L of liquid; LPG liquid is about 0.54 kg/L, so about 23 kg. Overfilling to 100 percent would leave no room for expansion with heat. Check: 50 x 0.85 = 42.5 L and 42.5 x 0.54 = 22.95 kg. This is a desk exercise only; filling is done solely by licensed, certified fillers.',
   'Build a hazard table: hazard, cause, effect, control, and the person responsible for each control, using the figures above.',
   'Table has at least 6 hazards and a control and owner for each; the fill and mass figures are correct to within 2 percent; no step tells a learner to handle gas.'),
  ('The legal and licensing frame', 'Evaluate', 5,
   'Distribution of gas is a regulated activity. The first task is to know what is needed and who decides.',
   ['List the kinds of approval to check: business licence or permission, premises approval, vehicle and driver rules, staff certification, equipment inspection, insurance.',
    'Separate what a seller may do from what only a licensed filler may do.',
    'Keep a compliance register with the status and date of each item.',
    'Check with the competent Russian authority and a qualified adviser before any step.'],
   'A register lists 10 items; 7 confirmed, 3 open. With 3 items open the plan states "no operation until all 10 are confirmed". Check: 7 + 3 = 10, so 70 percent are confirmed, but the stop rule applies until the share is 100 percent. Each open item has an owner, a date to ask the competent authority, and a note of the answer received.',
   'Build a compliance register with owners, dates, source of each rule and status, and write the stop rule at the top.',
   'At least eight approval types are listed with a status, an owner and a date; the stop rule is written; every item names the competent authority or adviser who confirms it.'),
  ('Cylinders: types, marks and checks', 'Apply', 4,
   'Each cylinder has marks for owner, capacity, test date and valve type. A cylinder past its test date or damaged must not be used.',
   ['Read the stamped marks: capacity, test date, next test.',
    'Inspect for dents, rust, valve damage and leaks by trained staff.',
    'Quarantine and tag suspect cylinders; return them to the owner for testing.',
    'Keep cylinder records: serial, owner, location, date.'],
   'Of 200 cylinders in a check, 6 are past test date and 4 are dented: 10 of 200 = 5 percent are quarantined and 190 stay in use.',
   'Fill in a cylinder inspection sheet for ten sample cylinders (photos).',
   'Defects found and quarantine decisions correct.'),
  ('Storage and handling rules', 'Evaluate', 5,
   'Storage is designed for safe distances, ventilation, no ignition and fire response. Only approved places may be used.',
   ['Store upright with valve caps on, secured against falling.',
    'Keep distances to buildings, drains and ignition sources as the rules require.',
    'Ventilate the area; ban smoking and open flame; use approved electrical fittings.',
    'Keep fire extinguishers and signs; limit quantity to the approved amount.'],
   'An approved store allows 100 cylinders x 23 kg = 2.3 tonnes. A delivery of 120 would exceed the limit by 20 cylinders (460 kg); the extra 20 are not accepted. Check: 120 - 100 = 20 and 20 x 23 = 460 kg, so the delivery would be 20 percent over the approved limit. The driver keeps the extra cylinders on the vehicle or returns them, and the refusal is logged with date and quantity.',
   'Audit a storage case study against a 12-point checklist covering distances, ventilation, ignition, fire cover, signs and quantity, and rate each fault by risk.',
   'All 12 points are marked pass or fail; each fault is rated high, medium or low with a reason; every high fault has a corrective action and a date; the quantity limit is checked.'),
  ('Transport and delivery', 'Apply', 5,
   'Vehicles, loading and driver training are controlled. Cylinders are secured, upright and not left in a hot closed vehicle.',
   ['Check the vehicle is approved and equipped for the load.',
    'Secure cylinders upright with valve protection; never exceed the load limit.',
    'Plan routes; avoid tunnels or crowded places if the rules require.',
    'Hand over with a leak check by a trained person and a record.'],
   'A truck is approved for 1,000 kg of gas product. Each full cylinder weighs 23 kg gas plus 22 kg steel = 45 kg; the maximum is 22 cylinders (990 kg). Check: 23 + 22 = 45 kg, 1,000 / 45 = 22.2 so 22 whole cylinders, and 22 x 45 = 990. A route of 20 customers with one cylinder each is 900 kg, 90 percent of the limit, leaving 100 kg unused. Only a trained, authorised driver may deliver.',
   'Plan a delivery route and load for 20 customers with weights, stop order, handover checks and the record kept at each stop.',
   'Total load is within the approved limit and shown in kg; the route lists all stops; each handover has a leak check by a trained person and a signed record; weather and heat controls are stated.'),
  ('Customer safety and installation', 'Apply', 4,
   'The customer must know how to use and store cylinders. Installation work is done only by qualified people.',
   ['Give a short safety briefing: ventilation, hose condition, leak check with soapy water, shut-off.',
    'Never advise customers to carry out repairs.',
    'Keep a complaint and incident log.',
    'Offer a hose and regulator replacement schedule from a qualified supplier.'],
   'A hose is 5 years old against a 3-year replacement limit set by the maker: it is replaced, and the sale of a new hose at 400 RUB is recorded. Check: 5 - 3 = 2 years overdue. The seller does not fit the hose; a qualified person does, and the date is noted so the next replacement falls due in 3 years.',
   'Write a one-page customer safety card covering ventilation, hose age, a soapy-water leak check, shut-off and who to call, in plain words.',
   'The card is correct, fits one page, uses words a customer understands, tells no customer to repair equipment, and was read back by a peer with at least 4 of 5 points recalled.'),
  ('Emergency response and incidents', 'Evaluate', 4,
   'Plans must be written, practised and posted. Staff know who to call and what not to do.',
   ['Leak: stop the work, remove ignition sources, move people away upwind, call the emergency service.',
    'Fire: do not fight a cylinder fire unless trained; evacuate.',
    'Write an incident report and tell the authority as required.',
    'Practise a drill twice a year.'],
   'A drill clears 12 staff and 3 customers from the depot in 90 seconds against a 120-second target; the time and any issues are logged. Check: 12 + 3 = 15 people cleared, and 90 s is 30 s inside the 120 s target, a margin of 25 percent (30 / 120). Even so, note issues such as a blocked exit and fix them before the next drill in six months.',
   'Write an emergency plan for a depot with roles, emergency numbers, leak and fire steps, assembly point, incident report form and a drill record.',
   'The plan has named roles, numbers, steps and a drill record; the drill time is compared with its target; the plan says staff do not fight a cylinder fire unless trained; it is reviewed twice a year.'),
  ('Unit cost and operating plan', 'Create', 4,
   'The plan joins compliance, safety, cost and service. Cost per cylinder must include the cost of safety and compliance.',
   ['List costs per cylinder: purchase, transport, storage, labour, inspection, insurance, losses.',
    'Add compliance costs such as training and equipment checks.',
    'Compute margin and break-even deliveries per month.',
    'State the stop rule: no operation without confirmed approvals.'],
   'Purchase 900 RUB, transport 60, storage 20, labour 70, compliance and insurance 50: cost 1,100 RUB. Sell at 1,300 RUB: margin 200 RUB (15.4 percent). Fixed cost 60,000 RUB per month needs 300 cylinders to break even. Check: 900 + 60 + 20 + 70 + 50 = 1,100; 1,300 - 1,100 = 200; 200 / 1,300 = 15.4 percent; 60,000 / 200 = 300. If compliance cost rises by 30 RUB, margin is 170 RUB and break-even becomes 353 cylinders (60,000 / 170), so safety cost must never be cut.',
   'Build the operating plan and cost model with unit cost, margin, break-even, a price or volume test and the stop rule on the first page.',
   'Costs add up and are within 2 percent; compliance cost is included; the test is shown; the stop rule is written; every licence to confirm is listed with the authority that decides.')],
 quiz=[
  ('Why does LPG collect in low places?', 'It is heavier than air, so a leak sinks and gathers in pits and cellars, where one spark can ignite it.'),
  ('Why is a cylinder never filled completely?', 'Liquid expands with heat, so the cylinder needs free space to avoid dangerous pressure; only licensed fillers set the fill level.'),
  ('What do you do with a cylinder past its test date?', 'Quarantine it and return it to the owner for testing.'),
  ('Who may fill cylinders?', 'Only a licensed and approved filler with certified staff.'),
  ('How is a customer leak check done?', 'With soapy water by a trained person, never a flame.'),
  ('What should happen in a gas leak?', 'Stop work, remove ignition sources, move people away and call the emergency service.'),
  ('Why keep a compliance register?', 'To track every licence, approval and check, and stop work if one is open.'),
  ('How do you find a truck\'s maximum cylinders?', 'Divide the approved load by the weight of one full cylinder.'),
  ('Should a seller advise customers to repair regulators?', 'No; only qualified people do that.'),
  ('Who confirms licence rules?', 'The competent Russian authority and a qualified local adviser.')],
 rubric=[
  ('Hazard understanding', 'Hazards misstated', 'Hazards and controls correct', 'Explains how controls fail'),
  ('Compliance', 'Approvals missing', 'Register complete with a stop rule', 'Prepares inspection readiness'),
  ('Checklists', 'Faults missed', 'Storage and delivery faults found and rated', 'Proposes fixes with costs'),
  ('Emergency plan', 'No plan', 'Plan with roles, steps and drill', 'Reviews a drill and improves it'),
  ('Cost model', 'Safety cost left out', 'Cost includes compliance and is within 2 percent', 'Tests volume and price changes')],
 ladder=[
  'L1 Basic: can say why gas is dangerous and that only trained, licensed people handle it.',
  'L2 Awareness: can read cylinder marks and spot an obvious defect to report.',
  'L3 Foundation: can complete a storage checklist and explain emergency steps.',
  'L4 Practitioner: can prepare a compliance-first plan with checklists, records and cost model (desk-based).',
  'L5 Specialist: can run a licensed depot function with certified training under authority approval.',
  'L6 Advanced: can lead a licensed distribution operation, audits and incident management.',
  'L7 Super expert: can shape safety practice and train others across a region, under the competent authority.'],
 jobs=[
  ('Depot assistant', 'Supports records and checks at a licensed depot under supervision.'),
  ('Delivery driver trainee', 'Trains toward certified delivery under a licensed operator.'),
  ('Compliance clerk', 'Keeps the register and records for a distributor.'),
  ('Customer safety officer', 'Gives safety briefings and logs incidents.'),
  ('Licensed distributor manager', 'Runs a lawful operation after all approvals are in place.')],
 next='Next generic courses: Workplace Safety; Fire Safety Awareness; Logistics and Delivery.')
]
